apply.script:
Stop-Process -Name explorer -Force -ErrorAction SilentlyContinue
      $timeout = 5; while ($timeout -gt 0 -and !(Get-Process explorer -ErrorAction SilentlyContinue)) { Start-Sleep -Milliseconds 500; $timeout -= 0.5 }
      if (!(Get-Process explorer -ErrorAction SilentlyContinue)) { Start-Process explorer.exe }

